INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '自転車通勤への切り替え', '半年ほど前、電車通勤から自転車通勤に切り替えてみた。最初のうちは坂道で息が切れ、汗だくで出社することに抵抗があった。（1）、慣れてくると自然と体力がつき、むしろ一日の始まりに心地よい爽快感を得られるようになった。

時間だけを考えれば電車のほうが早いこともある。（2）、季節の変化を肌で感じながら移動できることには、電車にはない魅力があると思う。

