INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '語学アプリでの継続学習', '三日坊主で終わることを覚悟しつつ、語学学習アプリを使った学習を始めてみた。最初の一週間は毎日十分程度しか続かず、正直あまり自信がなかった。（1）、通知機能を活用して習慣化を意識したところ、気づけば半年以上継続できていた。

