INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', 'ベランダでのハーブ栽培', 'ベランダの小さな鉢で、バジルやミントなどのハーブを育て始めた。虫がつきやすく、水やりのタイミングも難しいと聞いていたので、正直あまり期待していなかった。（1）、こまめに様子を見るようにしていたら、思いのほか順調に育ち、料理に添えられるほどの量を収穫できるようになった。

