INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '初めての一人暮らし', '就職を機に、初めて実家を離れて一人暮らしを始めた。家事のすべてを自分でこなす必要があり、最初の一ヶ月は慣れない生活に戸惑うことばかりだった。（1）、少しずつ自分なりのやり方を見つけていくうちに、家事も苦にならなくなってきた。

実家にいた頃は当たり前だと思っていた家族の支えの大きさに、離れてみて初めて気づかされた。（2）、一人暮らしは大変なことも多いが、それ以上に得られるものも多いように思う。

