INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '友人への手紙', 'スマートフォンで簡単に連絡が取れる時代だからこそ、あえて年に数回、友人に手紙を書くようにしている。便箋を選び、言葉を選びながら時間をかけて書く作業は、メッセージアプリでのやりとりとは全く違う感覚がある。（1）、書き終えるまでに一時間以上かかることも珍しくない。

