INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '図書館の本整理ボランティア', '定年後の時間を使って、近所の図書館で本の整理を手伝うボランティアを始めた。若い頃から本が好きだったとはいえ、実際の作業は分類のルールを覚えることから始まり、思いのほか奥が深かった。（1）、続けるうちに本の背表紙を見ただけで置き場所が分かるようになり、達成感を覚えるようになった。

