INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '小学生の頃の将来の夢', '先日、実家に帰った際、小学生の頃に書いた将来の夢についての作文が出てきた。当時の夢は今の仕事とは全く違う分野のものだったが、読み返してみると、その根っこにある「人の役に立ちたい」という思いは今も変わっていないことに気づいた。（1）、具体的な形は変わっても、大切にしたい価値観は昔からずっと同じなのかもしれない。

子どもの頃に描いた夢がそのまま叶うことは少ないかもしれない。（2）、その夢の奥にある思いを見つめ直すことには、大きな意味があるように思う。

文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["つまり","ところが","たとえば","しかし"]', 0, '["前文の内容をまとめる形で結論を述べているため、「つまり」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA模試: 長文読解・接続詞穴埋め）', 100);
